import {cafeMenu} from './cafe-catalog.js';
import {cafeMenuPreviews} from './cafe-menu-previews.js';
const descriptions={cafe_latte:'绵密奶泡 · 温柔奶香',cafe_americano:'清爽纯粹 · 咖啡本味',cafe_mocha:'可可香气 · 奶沫柔软',cafe_seabreeze:'清新的海岛特调',cafe_sunset:'一杯橙色的黄昏',cafe_berry:'莓果香气 · 细密气泡',cafe_strawberry:'草莓与柔软的奶油',cafe_chocolate:'浓郁可可 · 绵软蛋糕',cafe_cherry:'酥皮里的樱桃果香',cafe_cupcake:'小小一份，甜得刚好',cafe_cinnamon:'温热肉桂 · 层层松软',cafe_waffle:'奶油与香脆格纹'};
export function createCafeMenu(shell,onOrder,onClose,onVisibility=()=>{}){
 const root=document.createElement('section');root.className='cafe-menu-book';root.hidden=true;root.setAttribute('aria-label','海风来信菜单');shell.append(root);let selected=[],category='drink',mode='here',pending=false;
 function render(){root.innerHTML=`<div class="cafe-book-head"><div><small>SEASIDE CAFE</small><h2>海风来信</h2></div><div class="cafe-menu-stamp">免费招待<br><span>慢慢享用</span></div><button data-menu-close aria-label="收起菜单">收起</button></div><div class="cafe-menu-tabs" role="tablist">${[['drink','咖啡'],['cocktail','鸡尾酒'],['dessert','甜品']].map(([id,name])=>`<button role="tab" data-category="${id}" aria-selected="${category===id}">${name}</button>`).join('')}</div><div class="cafe-book-items">${cafeMenu.filter(i=>i.kind===category).map(i=>`<button data-item="${i.id}" aria-pressed="${selected.includes(i.id)}"><img data-food-preview="${i.id}" alt=""><span><b>${i.name}</b><small>${descriptions[i.id]}</small></span><em>${selected.includes(i.id)?'✓':'＋'}</em></button>`).join('')}</div><div class="cafe-book-order"><div class="cafe-order-summary">${selected.length?selected.map(id=>cafeMenu.find(i=>i.id===id).name).join(' + '):'选一杯饮品，也可以搭配一份甜品'}</div><div class="cafe-order-mode"><button data-mode="here" aria-pressed="${mode==='here'}">在店享用</button><button data-mode="takeaway" aria-pressed="${mode==='takeaway'}">打包带走</button></div><button class="cafe-prepare" data-prepare ${!selected.length||pending?'disabled':''}>${pending?'正在交给主理熊…':'请主理熊准备'} <span>→</span></button></div>`;
  cafeMenuPreviews().then(images=>{for(const img of root.querySelectorAll('[data-food-preview]'))if(images[img.dataset.foodPreview])img.src=images[img.dataset.foodPreview]});
 }
 root.onclick=e=>{if(pending)return;if(e.target.closest('[data-menu-close]')){api.hide();onClose();return}const cat=e.target.closest('[data-category]'),item=e.target.closest('[data-item]'),choice=e.target.closest('[data-mode]');if(cat){category=cat.dataset.category;render()}else if(choice){mode=choice.dataset.mode;render()}else if(item){const id=item.dataset.item;if(selected.includes(id))selected=selected.filter(x=>x!==id);else{const dessert=cafeMenu.find(i=>i.id===id).kind==='dessert';selected=selected.filter(x=>(cafeMenu.find(i=>i.id===x).kind==='dessert')!==dessert);selected.push(id)}render()}else if(e.target.closest('[data-prepare]')&&selected.length)onOrder([...selected],mode)};
 const api={show(item){if(item){category='dessert';selected=selected.filter(id=>cafeMenu.find(i=>i.id===id).kind!=='dessert');selected.push(item)}root.hidden=false;render();onVisibility(true)},hide(){root.hidden=true;onVisibility(false)},busy(v){pending=v;render()},clear(){selected=[];pending=false;render()},get visible(){return !root.hidden}};return api;
}
